"""Printed 227–228: point tangent/normal proof and external length."""
from math import sqrt
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_reviewed_conics_intro import ellipse
from math12_native_geometry import geometry,path
VECTOR=geometry('Figure 8.11','Figure 8.11 — position vectors, contact A and tangent point P; CA perpendicular AP',[path([(75,285),(75,35)]),path([(45,265),(475,265)]),path(ellipse(310,140,80,80)),path([(75,265),(310,140)]),path([(75,265),(358,204)]),path([(75,265),(430,150)]),path([(310,140),(358,204)]),path([(262,276),(454,132)])],[(67,24,'y'),(482,271,'x'),(51,289,'O'),(262,126,'C(−g,−f)'),(349,231,'A(x₁,y₁)'),(420,145,'P(x,y)'),(458,126,'T'),(181,223,'r₂'),(255,255,'r₁'),(272,194,'r')],points=[{'x':310,'y':140},{'x':358,'y':204}],size=(520,320))
def external_tangent():
 c=(220,170);p=(380,65);r=80;v=(p[0]-c[0],p[1]-c[1]);d2=sum(x*x for x in v);t=(c[0]+r*r*v[0]/d2+r*sqrt(d2-r*r)*(-v[1])/d2,c[1]+r*r*v[1]/d2+r*sqrt(d2-r*r)*v[0]/d2)
 return geometry('Figure 8.12','Figure 8.12 — external point P, tangent PT and perpendicular radius CT',[path([(65,280),(65,35)]),path([(45,260),(430,260)]),path(ellipse(*c,r,r)),path([c,p]),path([c,t]),path([t,p])],[(57,25,'y'),(436,267,'x'),(45,288,'O'),(185,173,'C'),(383,60,'P(x₁,y₁)'),(t[0]+7,t[1]+17,'T'),(261,208,'r')],points=[{'x':c[0],'y':c[1]},{'x':t[0],'y':t[1]}],size=(470,320))
PAGES=[page('118_page_1.jpg',227,[paragraph('If r₁ and r₂ are the position vectors of A and the center C(−g,−f) of the circle relative to origin'),eq(r'r_1=(x_1,y_1)=x_1i+y_1j,\quad r_2=(-g,-f)=-gi-fj'),paragraph('then, from the Figure 8.11:'),VECTOR,eq(r'\overrightarrow{OC}+\overrightarrow{CA}=\overrightarrow{OA}'),eq(r'\overrightarrow{CA}=\overrightarrow{OA}-\overrightarrow{OC}=r_1-r_2=(x_1+g,y_1+f)=(x_1+g)i+(y_1+f)j'),paragraph('Let P(x,y) be any point on the tangent line AT, whose position vector is OP = (x,y) which gives:'),eq(r'\overrightarrow{OA}+\overrightarrow{AP}=\overrightarrow{OP}'),eq(r'\overrightarrow{AP}=\overrightarrow{OP}-\overrightarrow{OA}=r-r_1'),eq(r'=(x,y)-(x_1,y_1)=(x-x_1,y-y_1)=(x-x_1)i+(y-y_1)j'),paragraph('The equation of tangent to the circle (i) is obtained if AP is perpendicular to CA for which the dot product in between the vectors AP and AC equals zero:'),eq(r'\overrightarrow{AP}\cdot\overrightarrow{CA}=0'),eq(r'(x_1+g,y_1+f)\cdot(x-x_1,y-y_1)=0'),eq(r'(x_1+g)(x-x_1)+(y_1+f)(y-y_1)=0'),eq(r'xx_1+yy_1+gx+fy-(x_1^2+y_1^2+gx_1+fy_1)=0'),eq(r'xx_1+yy_1+gx+fy=x_1^2+y_1^2+gx_1+fy_1=-gx_1-fy_1-c,\quad\mathrm{result}\ (ii)'),eq(r'xx_1+yy_1+g(x+x_1)+f(y+y_1)+c=0','iii'),paragraph('The tangent equation to the circle x²+y² = a² at a point A(x₁,y₁) through result (iii) is:'),eq(r'xx_1+yy_1=a^2','iv'),paragraph('The procedure for the normal equation at a point (x₁,y₁) on the circle x²+y²+2gx+2fy+c = 0 is as under: If C(−g,−f) is the center of the circle and A(x₁,y₁) is a contact point, then the slope (y₁+f)/(x₁+g) of the required normal line develops the normal line CA at A(x₁,y₁):'),eq(r'y-y_1=\frac{y_1+f}{x_1+g}(x-x_1)'),eq(r'(y-y_1)(g+x_1)=(f+y_1)(x-x_1)'),eq(r'x(y_1+f)-y(x_1+g)+(gy_1-fx_1)=0','v'),paragraph('The normal equation to the circle x²+y² = a² at a point A(x₁,y₁) through result (v) is:'),eq(r'xy_1-yx_1=0','vi'),note('Require a genuine circle and A on its circumference. The tangent normal vector A−C must be nonzero. The source switches between AC and CA in its wording; their negatives give the same zero-dot-product condition. The normal’s slope quotient excludes x₁+g = 0, but the implicit equation (v) still handles that vertical normal. At a point circle A = C these formulas do not determine a unique tangent or normal.')]),
 page('118_page_2.jpg',228,[heading('Example 11'),paragraph('Find the equations of the tangent and normal to the circle x²+y² = 25 at a point (3,4).'),heading('Solution'),paragraph('Result (iv) is used to obtain the tangent equation to the given circle:'),eq(r'xx_1+yy_1=a^2\ \Rightarrow\ 3x+4y=25,\quad a^2=25,(x_1,y_1)=(3,4)'),paragraph('Result (vi) is used to obtain the normal equation to the given circle:'),eq(r'xy_1-yx_1=0\ \Rightarrow\ 4x-3y=0,\quad a^2=0,(x_1,y_1)=(3,4)'),note('The normal substitution line prints a² = 0; the circle still has a² = 25. The normal equation itself does not use the radius parameter and remains correct.'),
 heading('Example 12'),paragraph('Find the equations of the tangent and normal to the circle x²+y²−2x+4y+3 = 25 at a point (2,−3).'),heading('Solution'),paragraph('Result (iii) is used to obtain the tangent line to the given circle:'),eq(r'xx_1+yy_1+g(x+x_1)+f(y+y_1)+c=0'),eq(r'2x-3y+(-1)(x+2)+(2)(y-3)+3=0,\quad 2g=-2,2f=4,c=3'),eq(r'2x-3y-x-2+2y-6+3=0,\quad(x_1,y_1)=(2,-3)'),eq(r'x-y-5=0'),paragraph('Result (v) is used to obtain the normal line to the given circle:'),eq(r'x(y_1+f)-y(x_1+g)+(gy_1-fx_1)=0'),eq(r'x(-3+2)-y(2-1)+(3-4)=0,\quad2g=-2,2f=4,c=3'),eq(r'-x-y-1=0\ \Rightarrow\ x+y+1=0'),note('At (2,−3), the question’s left side equals 0, not its printed right side 25. Thus the stated point is not on that circle and a tangent/normal “at” it is undefined. Completing squares gives (x−1)²+(y+2)² = 27; the point is strictly inside, so no real tangent through it exists either. The source solution uses the different circle with right side 0, namely (x−1)²+(y+2)² = 2. For that apparent intended equation the displayed tangent x−y−5 = 0 and normal x+y+1 = 0 are correct. The two interpretations are kept explicit.'),
 heading('8.3.5 Length of a tangents to a circle from a given external point'),paragraph('The procedure of finding the length of the tangent drawn from the external point P(x₁,y₁) to the circle x²+y²+2gx+2fy+c = 0 is as under: Let P(x₁,y₁) be the given external point and PT be one of the two tangents drawn from point P to the circle'),eq(r'x^2+y^2+2gx+2fy+c=0','i'),external_tangent(),paragraph('Join CP and CT. C(−g,−f) is the center of the circle (i) and CT = √(g²+f²−c) is the radius of the circle (i). From the right-angled triangle PTC, the length of the tangent PT drawn from point P to the given circle is:'),eq(r'|PC|^2=|CT|^2+|PT|^2'),eq(r'|PT|^2=|PC|^2-|CT|^2=(x_1+g)^2+(y_1+f)^2-(g^2+f^2-c)'),eq(r'=x_1^2+y_1^2+2gx_1+2fy_1+c'),eq(r'|PT|=\sqrt{x_1^2+y_1^2+2gx_1+2fy_1+c}','ii'),note('For a genuine circle, the radicand is the power of P: |PC|²−r². It is positive at an external point, zero on the circumference and negative inside. A negative value means no real tangent length. The length belongs to the finite segment from P to its contact T, not the entire infinite tangent line.')])]
for p in PAGES:
 p.update(title='CONICS-I',visualStatus='Complete point tangent/normal proof and external tangent-length derivation with native perpendicular geometry',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':118,'side':'left' if p['page']==227 else 'right','reason':'Example 12 right side 25 enlarged and confirmed; complete source working retains incompatible right-side-zero interpretation'})
EXAMPLES=[]
for n,q,steps,ans in [
 ('11','Find the tangent and normal to x²+y² = 25 at (3,4).',['Check that the point lies on the circle: 3²+4² = 25.','The center is (0,0), so the nonzero radius vector to the contact is (3,4).','A tangent point (x,y) satisfies (3,4)·((x,y)−(3,4)) = 0.','Expanding gives 3x+4y = 25.','The normal line through the center in direction (3,4) has equation 4x−3y = 0.','Both lines contain (3,4). A tangent direction is (4,−3), whose dot product with the radius is 12−12 = 0, verifying perpendicularity.'],'Tangent 3x+4y = 25; normal 4x−3y = 0.'),
 ('12','Find tangent and normal to x²+y²−2x+4y+3 = 25 at (2,−3).',['First test the contact condition: at (2,−3), x²+y²−2x+4y+3 = 4+9−4−12+3 = 0.','The right side is 25, so the stated point is not on the stated circle. A tangent or normal at that point is therefore not defined.','Complete squares: (x−1)²+(y+2)² = 27, giving center (1,−2) and squared radius 27.','The point’s squared distance to the center is 1²+(−1)² = 2 < 27. It is inside, so there are no real tangents through it.','The textbook instead solves x²+y²−2x+4y+3 = 0. For this apparent intended circle, squared radius is 2 and the point is on its circumference.','Its radius vector at the point is (1,−1). The tangent equation is (x−2)−(y+3) = 0, or x−y−5 = 0.','The corresponding normal joins (1,−2) to (2,−3), giving x+y+1 = 0. Both pass through the point and their directions are perpendicular.','These two equations answer only the explicitly identified right-side-zero interpretation, not the question as printed.'],'As printed, no tangent/normal at (2,−3); for the apparent intended right side 0: tangent x−y−5 = 0, normal x+y+1 = 0.')]:
 EXAMPLES.append({'num':n,'title':'Tangent and Normal at a Point','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':228,'jpg':'118_page_2.jpg','verification':'Exact source circle equation, contact and incompatible worked equation visually checked'}]})
